(function(){
var params=new URLSearchParams(location.search);
var scene=params.get('scene')||'paging';
var variant=params.get('variant')==='fault'?'fault':'normal';
var views=document.querySelectorAll('.view');views.forEach(function(v){v.classList.add('hidden')});
var map={paging:'pagingView',retry:'retryView',wizard:'wizardView'};var el=document.getElementById(map[scene]||'pagingView');el.classList.remove('hidden');
var DATA=[['P01','北站'],['P02','南站'],['P03','北站'],['P04','南站'],['P05','北站'],['P06','南站'],['P07','北站'],['P08','南站']];
var page=1,station='all',pageSize=2;
var rows=document.getElementById('rows'),pageMeta=document.getElementById('pageMeta'),filterState=document.getElementById('filterState');
var prevBtn=document.getElementById('prevBtn'),nextBtn=document.getElementById('nextBtn');
function label(s){return s==='north'?'北站':(s==='south'?'南站':'全部')}
function filtered(){return DATA.filter(function(r){return station==='all'||r[1]===label(station)})}
function renderPaging(){var list=filtered(),total=list.length,pages=Math.max(1,Math.ceil(total/pageSize));if(page>pages)page=pages;if(page<1)page=1;
var start=(page-1)*pageSize,show=list.slice(start,start+pageSize);
if(variant==='fault'&&station==='north'&&page===2){show=[['P02','南站'],['P04','南站']]}
rows.innerHTML=show.map(function(r){return '<tr><td>'+r[0]+'</td><td>'+r[1]+'</td></tr>'}).join('');
pageMeta.textContent='共'+total+'条，'+page+'/'+pages+'页';filterState.textContent='当前筛选：'+label(station);
prevBtn.disabled=page<=1;nextBtn.disabled=page>=pages;}
if(scene==='paging'){document.getElementById('filterBtn').onclick=function(){station=document.getElementById('station').value;page=1;renderPaging()};
prevBtn.onclick=function(){page--;renderPaging()};nextBtn.onclick=function(){page++;renderPaging()};renderPaging();}
var dlg=document.getElementById('dlg'),tStatus=document.getElementById('tStatus'),tVolt=document.getElementById('tVolt'),tTime=document.getElementById('tTime'),tRetry=document.getElementById('tRetry'),tClose=document.getElementById('tClose');
var timer=null;
function setDlg(open){dlg.classList.toggle('hidden',!open);dlg.setAttribute('aria-hidden',open?'false':'true')}
function clearTimer(){if(timer){clearTimeout(timer);timer=null}}
function openDlg(){clearTimer();setDlg(true);tStatus.textContent='读取中…';tStatus.className='ok';tVolt.textContent='-';tTime.textContent='-';tRetry.disabled=true;tRetry.classList.add('hidden');timer=setTimeout(function(){tStatus.textContent='暂时无法读取';tStatus.className='bad';tRetry.classList.remove('hidden');tRetry.disabled=false},400)}
function retryRead(){clearTimer();tStatus.textContent='读取中…';tStatus.className='ok';tRetry.disabled=true;timer=setTimeout(function(){tStatus.textContent='读取成功';tStatus.className='ok';tVolt.textContent=variant==='fault'?'705 V':'750 V';tTime.textContent='2026-09-24 10:00:00';tRetry.classList.add('hidden');tRetry.disabled=true},600)}
if(scene==='retry'){document.getElementById('openTelemetry').onclick=openDlg;tRetry.onclick=retryRead;tClose.onclick=function(){clearTimer();setDlg(false)}}
var wStep1=document.getElementById('wStep1'),wStep2=document.getElementById('wStep2'),wName=document.getElementById('wName'),wQty=document.getElementById('wQty'),wErr=document.getElementById('wErr'),wErr2=document.getElementById('wErr2'),wSummary=document.getElementById('wSummary'),wAgree=document.getElementById('wAgree'),wPreview=document.getElementById('wPreview');
function qtyValid(){var raw=wQty.value.trim();var n=Number(raw);return raw!==''&&Number.isInteger(n)&&n>=1&&n<=5}
function showStep(one){wStep1.classList.toggle('hidden',!one);wStep2.classList.toggle('hidden',one);if(!one){wErr2.textContent='';wSummary.textContent='申请人：'+wName.value.trim()+'；数量：'+wQty.value.trim()}else{wErr.textContent=''}}
function nextFrom1(){var name=wName.value.trim();if(!name){showStep(true);wErr.textContent='请填写申请人';return false}if(!qtyValid()){showStep(true);wErr.textContent='数量须为1至5的整数';return false}wErr.textContent='';showStep(false);return true}
if(scene==='wizard'){showStep(true);document.getElementById('wNext1').onclick=nextFrom1;document.getElementById('wBack').onclick=function(){showStep(true)};document.getElementById('wPreviewBtn').onclick=function(){if(!nextFrom1())return;if(!wAgree.checked){wErr2.textContent='请勾选我已核对';wPreview.classList.add('hidden');return}wErr2.textContent='';var n=variant==='fault'?3:Number(wQty.value.trim());wPreview.innerHTML='<strong>预览</strong><div class=kv><span>申请人</span><span>'+wName.value.trim()+'</span><span>数量</span><span>'+n+'</span><span>状态</span><span class=ok>仅预览，未提交</span></div>';wPreview.classList.remove('hidden')}}
})();



